// Validate and prepare batch processing request
const items = $input.all();
const requestData = items[0].json;

// Validate required fields
if (!requestData.documents || !Array.isArray(requestData.documents)) {
  throw new Error('Missing or invalid documents array');
}

if (requestData.documents.length === 0) {
  throw new Error('Documents array is empty');
}

// Prepare batch configuration
const batchConfig = {
  batch_id: `batch_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  documents: requestData.documents,
  total_documents: requestData.documents.length,

  // Processing options (applied to all documents)
  chunking_strategy: requestData.chunking_strategy || 'semantic',
  chunk_size: requestData.chunk_size || 1000,
  chunk_overlap: requestData.chunk_overlap || 200,
  generate_embeddings: requestData.generate_embeddings !== false,
  ingest_to_vector: requestData.ingest_to_vector !== false,
  ingest_to_kg: requestData.ingest_to_kg !== false,

  // Batch options
  collection_name: requestData.collection_name || 'technical_bulletins',
  overwrite: requestData.overwrite || false,
  continue_on_error: requestData.continue_on_error !== false,
  max_concurrent: requestData.max_concurrent || 3,

  // Metadata
  status: 'processing',
  started_at: new Date().toISOString(),
  source: 'n8n_batch_workflow'
};

return { json: batchConfig };

// Split documents into individual processing items
const batchConfig = $input.first().json;
const documents = batchConfig.documents;

const processingItems = documents.map((doc, index) => ({
  batch_id: batchConfig.batch_id,
  document_index: index,
  total_documents: batchConfig.total_documents,

  // Document data
  filename: doc.filename,
  document_data: doc.document_data,
  file_path: doc.file_path,

  // Processing options
  chunking_strategy: batchConfig.chunking_strategy,
  chunk_size: batchConfig.chunk_size,
  chunk_overlap: batchConfig.chunk_overlap,
  generate_embeddings: batchConfig.generate_embeddings,
  ingest_to_vector: batchConfig.ingest_to_vector,
  ingest_to_kg: batchConfig.ingest_to_kg,

  // Collection settings
  collection_name: batchConfig.collection_name,
  overwrite: batchConfig.overwrite,
  continue_on_error: batchConfig.continue_on_error,

  // Individual processing ID
  processing_id: `${batchConfig.batch_id}_doc_${index}`
}));

return processingItems.map(item => ({ json: item }));

// Collect and format individual document results
const items = $input.all();
const batchConfig = $('Validate Batch Request').first().json;

const results = items.map(item => {
  const result = item.json;
  return {
    processing_id: result.processing_id,
    document_index: result.document_index || 0,
    filename: result.filename,
    success: result.success || false,
    document_id: result.document_id,
    chunks_created: result.chunks_created || 0,
    kg_ingestion: result.kg_ingestion,
    enrichment_summary: result.enrichment_summary,
    processing_time_ms: result.total_processing_time_ms || 0,
    error: result.error || null
  };
});

// Calculate batch statistics
const successful = results.filter(r => r.success).length;
const failed = results.length - successful;
const totalChunks = results.reduce((sum, r) => sum + (r.chunks_created || 0), 0);
const totalProcessingTime = results.reduce((sum, r) => sum + (r.processing_time_ms || 0), 0);

// Calculate quality metrics
const qualityScores = results
  .filter(r => r.enrichment_summary)
  .map(r => r.enrichment_summary);

const avgCompleteness = qualityScores.length > 0 
  ? qualityScores.reduce((sum, s) => sum + (s.completeness_score || 0), 0) / qualityScores.length 
  : 0;

const avgConfidence = qualityScores.length > 0 
  ? qualityScores.reduce((sum, s) => sum + (s.extraction_confidence || 0), 0) / qualityScores.length 
  : 0;

const batchResult = {
  batch_id: batchConfig.batch_id,
  status: failed === 0 ? 'completed' : (successful > 0 ? 'partial_success' : 'failed'),

  // Summary statistics
  total_documents: batchConfig.total_documents,
  successful_documents: successful,
  failed_documents: failed,
  total_chunks_created: totalChunks,

  // Processing metadata
  total_processing_time_ms: totalProcessingTime,
  avg_processing_time_ms: Math.round(totalProcessingTime / results.length),
  completed_at: new Date().toISOString(),

  // Quality metrics
  quality_metrics: {
    avg_completeness_score: Math.round(avgCompleteness * 1000) / 1000,
    avg_extraction_confidence: Math.round(avgConfidence * 1000) / 1000,
    documents_with_quality_data: qualityScores.length
  },

  // Individual results
  document_results: results,

  // Configuration used
  processing_config: {
    chunking_strategy: batchConfig.chunking_strategy,
    collection_name: batchConfig.collection_name,
    generate_embeddings: batchConfig.generate_embeddings,
    ingest_to_kg: batchConfig.ingest_to_kg
  }
};

return { json: batchResult };

// Handle batch processing errors
const error = $input.first().json;
const batchConfig = $('Validate Batch Request').first().json;

const errorResponse = {
  batch_id: batchConfig.batch_id,
  status: 'error',
  error_message: error.message || error.error || 'Unknown batch processing error',
  error_details: error,
  failed_at: new Date().toISOString(),

  // Include batch configuration for debugging
  batch_config: {
    total_documents: batchConfig.total_documents,
    collection_name: batchConfig.collection_name,
    chunking_strategy: batchConfig.chunking_strategy
  }
};

return { json: errorResponse };
